Q = [
make(1, "跑步後體溫上升，身體啟動排汗與皮膚血流增加，這組反應的共同方向是？", {"A": "增加散熱以削弱體溫上升的偏離", "B": "讓體溫持續升高以配合運動", "C": "停止循環以保存所有熱量", "D": "把汗水直接轉成血糖"}, "A", "排汗蒸發與皮膚血流增加有助於把熱帶到體表並散出，反應方向是抵銷體溫上升，符合負回饋。", "先找內在條件的偏離方向，再檢查反應是否削弱該偏離。", ["標出跑步造成的體溫上升。", "列出排汗與皮膚血流的散熱作用。", "確認這些反應讓體溫上升趨勢減弱。", "排除持續升溫和停止循環等相反描述。", "因此選 A。"], "easy"),
make(2, "吃完含醣餐點後，血糖上升、數小時後回到原先範圍，哪個系統合作說明最完整？", {"A": "消化吸收使葡萄糖進入血液，內分泌調節與細胞利用共同降低偏高血糖", "B": "呼吸系統把所有葡萄糖排出體外", "C": "骨骼系統把葡萄糖固定成骨頭", "D": "腎臟一定把所有葡萄糖濾成尿液"}, "A", "消化系統提供吸收來源，胰島素等內分泌調節與細胞利用、肝糖合成共同使血糖回到範圍，不能把全部變化歸給單一器官。", "依序追蹤物質來源、訊息調節與目標器官，而非看到結果就指定單一系統。", ["先指出葡萄糖來自醣類消化吸收。", "再找出血糖偏高時的內分泌訊息。", "連結細胞利用與肝糖合成的反應。", "排除呼吸、骨骼或腎臟全量排出的錯誤路徑。", "所以選 A。"], "medium"),
make(3, "流汗後水分減少，口渴和尿量減少分別代表哪種調節方向？", {"A": "促進補水與減少水分流失，讓體內水分回到適當範圍", "B": "加速排水並抑制飲水，讓水分更快下降", "C": "只改變血糖，與水分無關", "D": "讓腎臟停止所有過濾功能"}, "A", "口渴促使飲水，腎臟可透過調整再吸收與尿量保留水分，兩者共同抵銷流汗造成的水分減少。", "把行為反應和器官反應分開，再確認兩者是否朝補水與保水方向。", ["指出流汗造成水分偏低。", "把口渴連到飲水行為。", "把尿量減少連到腎臟保水調節。", "排除增加排水、只談血糖和停止全部功能。", "完整答案是 A。"], "easy"),
make(4, "若要研究跑步強度對體溫恢復時間的影響，哪個設計最公平？", {"A": "固定環境溫度、運動時間、測量位置與補水方式，只改變跑步強度", "B": "高強度組在室內，低強度組在戶外，並用不同溫度計", "C": "只記錄恢復最快的一次", "D": "每組同時改變強度、時間、衣服與補水量"}, "A", "研究跑步強度時，其他會影響體溫和恢復的條件應固定，並以相同測量方法比較恢復時間。", "先鎖定一項自變因，再逐項找出會干擾體溫的控制變項。", ["指定跑步強度為主要自變因。", "固定環境、時間、衣服、測量位置與補水條件。", "用相同時間間隔記錄體溫回復曲線。", "保留重複資料，不挑最理想結果。", "故選 A。"], "medium"),
make(5, "『體內恆定』最準確的描述是什麼？", {"A": "重要內在條件在調節下維持於可生存的範圍，不代表每刻完全相同", "B": "所有體溫、血糖和水分永遠固定在同一數字", "C": "只要一項指標正常，其他系統不必合作", "D": "只在生病時才需要恆定調節"}, "A", "恆定是動態調節，使條件維持在適合細胞工作的範圍；吃飯、運動和環境仍可造成暫時變動。", "先排除『完全不變』，再確認調節的目標是範圍而非單一數值。", ["找出題目中的體溫、血糖和水分等內在條件。", "確認它們會因活動或環境暫時改變。", "把調節結果寫成可生存的範圍。", "排除固定數字與只靠單一系統的說法。", "因此答案是 A。"], "easy"),
make(6, "下列哪個箭頭最能表示水分不足時的負回饋？", {"A": "水分下降→口渴與腎臟保水增加→飲水／尿量調整→水分回升", "B": "水分下降→尿量增加→水分更低，仍稱負回饋", "C": "水分下降→停止口渴→水分必然回升", "D": "水分下降→只增加肺泡數量→不需飲水"}, "A", "水分不足會引發口渴和腎臟保水，飲水與尿量調整使水分回升，反應削弱原來的下降，符合負回饋。", "逐箭頭檢查偏離、偵測、反應和結果是否形成抵銷關係。", ["先標出原始偏離是水分下降。", "找出感受與行為反應：口渴和飲水。", "加入腎臟調整再吸收與尿量。", "確認結果是水分回升而非繼續下降。", "完整模型為 A。"], "medium"),
make(7, "運動時循環系統在體內恆定中最適合被描述成什麼？", {"A": "運送氧氣、養分、代謝物與激素，連接各器官但不單獨完成所有調節", "B": "獨自決定所有器官的反應，不需神經或激素", "C": "只把汗水運到皮膚，不運送氣體", "D": "把體溫直接固定成一個數字"}, "A", "循環系統是運輸網，運送氣體、養分、代謝物和激素，使器官能協作，但偵測與調節仍需其他系統參與。", "區分『運輸角色』和『調節命令或器官執行』，避免一個系統包辦全部功能。", ["列出循環中可運送的物質。", "確認激素和氣體需靠血液到達目標。", "指出神經、內分泌與器官仍各有角色。", "排除只運汗水和獨自決定的說法。", "故選 A。"], "medium"),
make(8, "某人運動後體溫較高，但只量一次就宣稱『排汗一定是唯一降溫原因』，問題在哪裡？", {"A": "還需記錄風速、濕度、皮膚血流與運動量等替代因素，單次資料不能證明唯一原因", "B": "只要量到體溫，就已證明所有降溫機制", "C": "排汗與體溫永遠無關", "D": "運動後體溫不可能改變"}, "A", "體溫變化可能同時受環境、蒸發、皮膚血流與運動量影響；單次體溫資料不足以把結果歸因於唯一機制。", "把觀察到的相關和可排他的因果分開，補列需要控制的變因。", ["確認資料只顯示運動後的體溫。", "列出排汗以外的散熱與環境因素。", "設計多次測量與適當對照。", "刪除『唯一』等超出證據範圍的字句。", "因此 A 是合理判讀。"], "hard"),
make(9, "下列哪一項正確區分神經與內分泌在恆定調節中的特色？", {"A": "神經訊息通常較快速且作用較局部；激素經血液運送，作用可較廣泛且持久", "B": "神經系統只運送血液；內分泌系統只運送氧氣", "C": "兩者完全沒有共同目標，不能共同調節", "D": "激素一定比神經訊息快且只作用一秒"}, "A", "神經傳遞通常快速且具有較明確的路徑，激素經血液到達具受體的細胞，作用範圍與持續時間可不同；兩者可協同維持恆定。", "比較傳遞方式、速度與作用範圍，不把『通常』誤讀成沒有例外的絕對規則。", ["先比對神經元傳訊息和血液運送激素。", "再比較一般作用速度與持續時間。", "保留兩者共同調節器官系統的功能。", "排除把系統功能互換或寫成絕對速度。", "所以選 A。"], "medium"),
make(10, "要整合體溫、血糖和水分三個案例，最適合使用哪個通用模型？", {"A": "內在條件改變→偵測→神經／激素訊息→目標器官反應→條件回到範圍", "B": "外界刺激→器官直接自行反應→永遠不需中樞或激素", "C": "所有條件改變→腎臟排出全部物質→回到零", "D": "測量一次→直接宣稱所有系統機制相同"}, "A", "三個案例都可用偏離、偵測、協調訊息、目標器官反應與回到範圍的鏈條理解，但具體器官和訊息仍依案例不同。", "先建立共通的因果骨架，再填入每個案例的具體器官與物質。", ["找出案例的內在條件和偏離方向。", "安排感受或偵測與訊息傳遞階段。", "填入汗腺、胰島或腎臟等目標器官。", "確認結果是抵銷偏離而非把數值歸零。", "因此選 A。"], "hard"),
]

for index, target in {2: "B", 4: "C", 6: "D", 8: "B", 10: "C"}.items():
    q = Q[index - 1]
    m = {o["id"]: o["text"] for o in q["options"]}
    m["A"], m[target] = m[target], m["A"]
    q["options"] = [{"id": k, "text": m[k]} for k in ("A", "B", "C", "D")]
    q["answer"]["value"] = target
    q["solutionSteps"] = [s.replace("選 A", f"選 {target}").replace("為 A", f"為 {target}") for s in q["solutionSteps"]]

for q in Q:
    (OUT / f"{q['id']}.json").write_text(json.dumps(q, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
print(f"rewrote {len(Q)} questions")
